		return super.delete(modulePath);
	}
	delete(fsPath) {
		return this.deleteByModuleId(this.normalizePath(fsPath));
	}
	invalidateModule(mod) {
		delete mod.evaluated;
		delete mod.resolving;
		delete mod.promise;
		delete mod.exports;
